export function parseUnstakeInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>
): ParsedUnstakeInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 26) {
    // TODO: Coded error.
    throw new Error("Not enough accounts")
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === STAKE_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      programConfig: getNextAccount(),
      staker: getNextAccount(),
      collection: getNextAccount(),
      stakeRecord: getNextAccount(),
      nftRecord: getNextOptionalAccount(),
      rewardMint: getNextOptionalAccount(),
      stakeTokenVault: getNextOptionalAccount(),
      rewardReceiveAccount: getNextOptionalAccount(),
      nftMint: getNextAccount(),
      nftToken: getNextAccount(),
      feesWallet: getNextAccount(),
      nftMetadata: getNextAccount(),
      tokenRecord: getNextOptionalAccount(),
      custodyTokenRecord: getNextOptionalAccount(),
      masterEdition: getNextAccount(),
      nftCustody: getNextOptionalAccount(),
      tokenAuthority: getNextOptionalAccount(),
      nftAuthority: getNextAccount(),
      owner: getNextAccount(),
      tokenProgram: getNextAccount(),
      associatedTokenProgram: getNextAccount(),
      systemProgram: getNextAccount(),
      metadataProgram: getNextAccount(),
      sysvarInstructions: getNextAccount(),
      authRules: getNextOptionalAccount(),
      authRulesProgram: getNextOptionalAccount(),
    },
    data: getUnstakeInstructionDataDecoder().decode(instruction.data),
  }
}
